def main():
    coverage = json.loads((AUDIT / 'FOCUSED_SPELL_SOURCE_PREPARATION_COVERAGE.json').read_text(encoding='utf-8'))
    assert len(coverage['cohortFiles']) == 15 and coverage['distinctPreparedPendingSpellIds'] == 232
    prepare(
        prefix='TRANSMUTATION_RANK5', title='Rank-five Transmutation source audit', questions=QUESTIONS,
        selector=lambda r: r['operational'] is None and 'Transmutation' in r['schools'] and min(v['rank'] for v in r['classAccess'].values()) == 5,
        expected_count=8, question_prefix='TR5', prior_files=coverage['cohortFiles'], expected_prior_count=232,
        counterpart_ids=['stoneflesh', 'shield', 'shapechange', 'magehand', 'gust', 'feather-fall'],
        pending_ids=['fabricate', 'creation', 'disable-limb', 'steel-skin', 'mage-hand'],
        extra_excerpts={
            'EQUIPMENT_ACQUISITION_PLAYTEST.md': ['Armor and shields', 'Equipment grade', 'Object damage and Sunder', 'Repair'],
            'CONDITIONS_PLAYTEST.md': ['Petrified', 'Grappled'],
            'CONTROL_STATES_PLAYTEST.md': ['Speed arbitration'],
            'CREATURE_LIFECYCLE_PLAYTEST.md': ['At the table', 'Different kinds of creature life', 'Stats and ownership'],
            'CRAFTING_HARVEST_PLAYTEST.md': None,
            'FISHING_RECIPE_PLAYTEST.md': ['Real material recovery'],
        },
        introduction='Eight complete sources preserve the60ft-radius terrain conversion,six-recipient ward,real stone limb,two material-conversion modes and object/creature telekinesis. Awaken is only a mechanical source question about the stated sentience/language changes; no soul or cosmology conclusion is adopted. Real material conversion is retained and its finite inventory/economy consequences require explicit review. Mining decisions are still pending and are not presumed here.',
        future_dispatch='Prepared only while the Mining/shared gathering-tool source conference is active. Rebase the then-current Mining and other dependencies before future dispatch. Preserve this source revision, obtain source decisions, author exact cards and return them for separate review. Cosmology remains after verified GitHub push.')


if __name__ == '__main__':
    main()
